import json
m = 7
Pa = [-1] * m; Pb = [-1] * m
def start(a):
    return (a * 40503) % m
def ins(a, b):
    j = start(a)
    while Pa[j] not in (a, -1):
        j = (j + 1) % m
    Pa[j] = a; Pb[j] = b
def get(a):
    j = start(a)
    for _ in range(m):
        if Pa[j] == a:
            return Pb[j]
        if Pa[j] == -1:
            return -1
        j = (j + 1) % m
    return -1
for a, b in [(1, 20), (8, 21), (3, 22)]:
    ins(a, b)
print(json.dumps({"start1": start(1), "start8": start(8), "get8": get(8), "get3": get(3), "get2": get(2)}))
